import{_ as e,o as r,c as a,a5 as d}from"./chunks/framework.B5tqjWbr.js";const c=JSON.parse('{"title":"PP-08 三电平 NPC/T-type/ANPC 拓扑基础 - 知识检查","description":"","frontmatter":{"date":"2026-06-11T00:00:00.000Z","section":"电机控制","chapter":"power-path","chapterTitle":"功率链路","chapterOrder":40,"category":"功率链路","source":"motor","visibility":"public","title":"PP-08 三电平 NPC/T-type/ANPC 拓扑基础 - 知识检查","tags":["motor-control"],"status":"learning","summary":"**模块编号：** PP-08 **题目数量：** 8 **验收目标：** 能画出关键开关状态、电流路径、中点电位影响，并能说明三电平拓扑与二电平逆变器在损耗、电压应力和控制复杂度上的差异。","navGroup":"基础与硬件","navGroupOrder":20},"headers":[],"relativePath":"content/motor/power-path/PP-08-assessment.md","filePath":"content/motor/power-path/PP-08-assessment.md","lastUpdated":null}'),o={name:"content/motor/power-path/PP-08-assessment.md"};function n(s,t,l,h,i,g){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="pp-08-三电平-npc-t-type-anpc-拓扑基础-知识检查" tabindex="-1">PP-08 三电平 NPC/T-type/ANPC 拓扑基础 - 知识检查 <a class="header-anchor" href="#pp-08-三电平-npc-t-type-anpc-拓扑基础-知识检查" aria-label="Permalink to &quot;PP-08 三电平 NPC/T-type/ANPC 拓扑基础 - 知识检查&quot;">​</a></h1><p><strong>模块编号：</strong> PP-08<br><strong>题目数量：</strong> 8<br><strong>验收目标：</strong> 能画出关键开关状态、电流路径、中点电位影响，并能说明三电平拓扑与二电平逆变器在损耗、电压应力和控制复杂度上的差异。</p><hr><h2 id="_1-拓扑识别" tabindex="-1">1. 拓扑识别 <a class="header-anchor" href="#_1-拓扑识别" aria-label="Permalink to &quot;1. 拓扑识别&quot;">​</a></h2><p><strong>问题：</strong> NPC 三电平桥臂输出 <code>+Vdc/2、0、-Vdc/2</code> 三个电平时，零电平通常由哪类器件路径形成？</p><p>A. 上下主开关同时导通<br> B. 中间开关与钳位二极管/中点路径共同形成<br> C. 仅由母线电容自然分压形成<br> D. 仅由续流二极管随机形成</p><p><strong>答案：</strong> B</p><p><strong>验收点：</strong> 回答必须说明零电平与中点电流有关，而不是只说“中点电压为 0”。</p><hr><h2 id="_2-开关状态表" tabindex="-1">2. 开关状态表 <a class="header-anchor" href="#_2-开关状态表" aria-label="Permalink to &quot;2. 开关状态表&quot;">​</a></h2><p><strong>问题：</strong> 给出一相 NPC 桥臂三种输出电平对应的开关状态表，并标注非法状态。</p><p><strong>参考答案：</strong></p><table tabindex="0"><thead><tr><th>输出电平</th><th style="text-align:right;">S1</th><th style="text-align:right;">S2</th><th style="text-align:right;">S3</th><th style="text-align:right;">S4</th><th>说明</th></tr></thead><tbody><tr><td><code>+Vdc/2</code></td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td>上半母线输出</td></tr><tr><td><code>0</code></td><td style="text-align:right;">0</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td>中点钳位输出</td></tr><tr><td><code>-Vdc/2</code></td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>下半母线输出</td></tr><tr><td>非法</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td>可能直通或无有效续流路径</td></tr></tbody></table><p><strong>验收点：</strong> 状态表必须包含互补约束和死区约束。</p><hr><h2 id="_3-器件应力" tabindex="-1">3. 器件应力 <a class="header-anchor" href="#_3-器件应力" aria-label="Permalink to &quot;3. 器件应力&quot;">​</a></h2><p><strong>问题：</strong> 在理想均压条件下，三电平 NPC 单个主开关的关断电压应力约为多少？</p><p><strong>答案：</strong> 约为 <code>Vdc/2</code>，但工程设计仍需考虑中点偏移、暂态尖峰、均压误差和器件裕量。</p><hr><h2 id="_4-中点电流路径" tabindex="-1">4. 中点电流路径 <a class="header-anchor" href="#_4-中点电流路径" aria-label="Permalink to &quot;4. 中点电流路径&quot;">​</a></h2><p><strong>问题：</strong> 为什么三电平拓扑必须关注中点电位平衡？</p><p><strong>参考答案：</strong> 零矢量和小矢量会使某些相电流流入或流出直流母线中点，导致上下母线电容电压不相等。中点漂移会改变器件电压应力、调制线性区和输出电压误差。</p><p><strong>验收点：</strong> 必须能结合电流方向说明“哪个开关状态会充/放上、下电容”。</p><hr><h2 id="_5-npc-与-t-type-对比" tabindex="-1">5. NPC 与 T-type 对比 <a class="header-anchor" href="#_5-npc-与-t-type-对比" aria-label="Permalink to &quot;5. NPC 与 T-type 对比&quot;">​</a></h2><p><strong>问题：</strong> 简述 NPC 与 T-type 的主要工程差异。</p><p><strong>参考答案：</strong></p><ul><li>NPC：钳位二极管/钳位器件路径清晰，适合较高电压等级，但钳位器件损耗和中点平衡复杂。</li><li>T-type：零电平路径器件少、导通损耗可能更低，适合中压高效率场景，但器件耐压组合和驱动保护要求更高。</li></ul><hr><h2 id="_6-仿真检查" tabindex="-1">6. 仿真检查 <a class="header-anchor" href="#_6-仿真检查" aria-label="Permalink to &quot;6. 仿真检查&quot;">​</a></h2><p><strong>任务：</strong> 在仿真中设置 <code>Vdc = 600 V</code>，调制比 <code>m = 0.8</code>，输出 50 Hz 正弦基波。</p><p><strong>验收标准：</strong></p><table tabindex="0"><thead><tr><th>指标</th><th>阈值</th></tr></thead><tbody><tr><td>相电压电平</td><td>只能出现 <code>+300 V、0、-300 V</code> 三类理想电平</td></tr><tr><td>duty 合法性</td><td>所有开关占空比在 <code>[0, 1]</code></td></tr><tr><td>中点偏移</td><td>稳态偏移小于 <code>Vdc</code> 的 5%，否则必须解释原因</td></tr></tbody></table><hr><h2 id="_7-故障分析" tabindex="-1">7. 故障分析 <a class="header-anchor" href="#_7-故障分析" aria-label="Permalink to &quot;7. 故障分析&quot;">​</a></h2><p><strong>问题：</strong> 若中点电压持续上漂，应优先检查哪些问题？</p><p><strong>参考答案：</strong> 冗余小矢量选择、零电平作用时间分配、三相电流方向、母线电容不匹配、采样极性、死区导致的等效电压误差。</p><hr><h2 id="_8-与电机控制连接" tabindex="-1">8. 与电机控制连接 <a class="header-anchor" href="#_8-与电机控制连接" aria-label="Permalink to &quot;8. 与电机控制连接&quot;">​</a></h2><p><strong>问题：</strong> 为什么 PP-08 是 PP-09 三电平 SVPWM 和 lxfoc 未来三电平接口的前置模块？</p><p><strong>参考答案：</strong> 调制算法必须以开关状态、电平定义、冗余矢量和中点电流路径为输入。若拓扑状态表错误，后续 SVPWM 扇区、占空比和中点平衡策略都会失效。</p><hr><h2 id="评分" tabindex="-1">评分 <a class="header-anchor" href="#评分" aria-label="Permalink to &quot;评分&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">得分</th><th>评价</th></tr></thead><tbody><tr><td style="text-align:right;">7-8</td><td>可进入 PP-09 三电平 SVPWM</td></tr><tr><td style="text-align:right;">5-6</td><td>需要补充中点电流路径和开关状态</td></tr><tr><td style="text-align:right;">&lt;5</td><td>需要重新学习三电平桥臂基础</td></tr></tbody></table>',44)])])}const P=e(o,[["render",n]]);export{c as __pageData,P as default};
